BEGIN;
CREATE TEMP TABLE _s463eb (xid INT, side CHAR(1), ob TEXT, oc INT, ov INT, nb TEXT, nc INT, nv INT, new_note TEXT, live_text TEXT, quotes_live BOOLEAN) ON COMMIT DROP;
INSERT INTO _s463eb VALUES
(12949,'T','apocalypse-of-abraham',18,4,'apocalypse-of-abraham',18,4,$n$*And the four beasts had each of them six wings about him; and they were full of eyes within: and they rest not day and night, saying, Holy, holy, holy, Yahuah Elohim (Lord God) Almighty, which was, and is, and is to come.* (Revelation 4:8). *And such was the appearance of their countenances, of a lion, of a man, of an ox, of an eagle: four heads were upon their bodies, so that the four creatures had sixteen faces; and each had six wings from their shoulders, and their sides, and their loins.* (Apocalypse of Abraham 18:4). John sees four beasts with six wings each, full of eyes, who rest not day and night as they say Holy, holy, holy. The verse before gives their four faces: *And the first beast was like a lion, and the second beast like a calf, and the third beast had a face as a man, and the fourth beast was like a flying eagle.* (Revelation 4:7). Abraham is shown the same creatures under the throne: a lion, a man, an ox and an eagle, with six wings each. Two witnesses see the same four faces and the same six wings around the throne.$n$,$n$And such was the appearance of their countenances, of a lion, of a man, of an ox, of an eagle: four heads were upon their bodies, so that the four creatures had sixteen faces; and each had six wings from their shoulders, and their sides, and their loins.$n$,true),
(48700,'S','apocalypse-of-abraham',9,7,'apocalypse-of-abraham',9,7,$n$Romans 4:17 — *(As it is written, I have made thee a father of many nations,) before him whom he believed, even Elohim (God), who quickeneth the dead, and calleth those things which be not as though they were.* The ages which 'shall come to pass' shewn Abraham in 9:7 are seen by the same faith that calls the not-yet as though it already were.$n$,$n$But abstain from every form of food that proceedeth out of the fire, and from the drinking of wine, and from anointing thyself with oil, forty days, and then set forth for me the sacrifice which I have commanded thee, in the place which I will shew thee, on a high mountain, and there I will shew thee the ages which have been created and established, made and renewed, by my Word, and I will make known to thee what shall come to pass in them on those who have done evil and practised righteousness in the generation of men."$n$,false),
(48702,'S','apocalypse-of-abraham',9,6,'apocalypse-of-abraham',9,6,$n$Genesis 15:13 — *And he said unto Abram, Know of a surety that thy seed shall be a stranger in a land that is not theirs, and shall serve them; and they shall afflict them four hundred years.* The 'ages (to come)' laid before Abraham in 9:6 are the very foretelling joined to the Genesis covenant — what shall come to pass upon the seed.$n$,$n$And in this sacrifice I will lay before thee the ages (to come), and make known to thee what is reserved, and thou shalt see great things which thou hast not seen hitherto; because thou hast loved to search me out, and I have named thee my Friend.$n$,false),
(48711,'S','apocalypse-of-abraham',10,11,'apocalypse-of-abraham',10,11,$n$Genesis 12:1 — *Now Yahuah (LORD) had said unto Abram, Get thee out of thy country, and from thy kindred, and from thy father's house, unto a land that I will shew thee.* The land the Eternal One hath prepared, for which Jaoel comes (Apocalypse of Abraham 10:11), is the land of the first calling-out.$n$,$n$I have been sent to bless thee now, and the land which the Eternal One, whom thou hast invoked, hath prepared for thee, and for thy sake have I wended my way upon the earth.$n$,false),
(48712,'S','apocalypse-of-abraham',10,16,'apocalypse-of-abraham',10,16,$n$Genesis 15:5 — *And he brought him forth abroad, and said, Look now toward heaven, and tell the stars, if thou be able to number them: and he said unto him, So shall thy seed be.* The generation prepared to spring from Abraham (Apocalypse of Abraham 10:16) is the innumerable seed shown as the stars.$n$,$n$For, lo, I have been appointed to be with thee and with the generation prepared to spring from thee; and with me Michael blesseth thee for ever.$n$,false),
(48713,'S','apocalypse-of-abraham',10,15,'apocalypse-of-abraham',10,15,$n$Genesis 15:9 — *And he said unto him, Take me an heifer of three years old, and a she goat of three years old, and a ram of three years old, and a turtledove, and a young pigeon.* The sacrifices Jaoel commands Abraham to fulfil (Apocalypse of Abraham 10:15) are the exact heifer, goat, ram, turtledove and pigeon of the Genesis covenant.$n$,$n$Go, fulfil the sacrifices commanded.$n$,false),
(48714,'S','apocalypse-of-abraham',10,10,'apocalypse-of-abraham',10,10,$n$1 Enoch 10:8 — *And the whole earth has been corrupted through the works that were taught by Azâzêl: to him ascribe all sin.* The corrupting reverence for dead idols burned away in Apocalypse of Abraham 10:10 is the same Azazel-system whose works defile the earth.$n$,$n$I am the one who was commissioned to set on fire thy father's house together with him, because he displayed reverence for dead idols.$n$,false),
(48715,'S','apocalypse-of-abraham',10,10,'apocalypse-of-abraham',10,10,$n$Isaiah 44:15 — *Then shall it be for a man to burn: for he will take thereof, and warm himself; yea, he kindleth it, and baketh bread; yea, he maketh a god, and worshippeth it; he maketh it a graven image, and falleth down thereto.* The wood that becomes a worshipped god is fit only for the fire that consumes the idol-house in Apocalypse of Abraham 10:10.$n$,$n$I am the one who was commissioned to set on fire thy father's house together with him, because he displayed reverence for dead idols.$n$,false),
(48716,'S','apocalypse-of-abraham',10,10,'apocalypse-of-abraham',10,10,$n$Isaiah 44:9 — *They that make a graven image are all of them vanity; and their delectable things shall not profit; and they are their own witnesses; they see not, nor know; that they may be ashamed.* The dead idols Terah reveres (Apocalypse of Abraham 10:10) are the very vanity Isaiah exposes.$n$,$n$I am the one who was commissioned to set on fire thy father's house together with him, because he displayed reverence for dead idols.$n$,false),
(48717,'S','apocalypse-of-abraham',10,10,'apocalypse-of-abraham',10,10,$n$Joshua 24:2 — *And Joshua said unto all the people, Thus saith Yahuah Elohim (the LORD God) of Yashar'el (Israel), Your fathers dwelt on the other side of the flood in old time, even Terah, the father of Abraham, and the father of Nachor: and they served other gods.* Terah's idolatrous house, marked for burning in Apocalypse of Abraham 10:10, is named outright in Israel's own record.$n$,$n$I am the one who was commissioned to set on fire thy father's house together with him, because he displayed reverence for dead idols.$n$,false),
(48718,'S','apocalypse-of-abraham',10,8,'apocalypse-of-abraham',10,8,$n$Psalm 74:14 — *Thou brakest the heads of leviathan in pieces, and gavest him to be meat to the people inhabiting the wilderness.* The menace of Leviathan that bows to His command (Apocalypse of Abraham 10:8) is the head Yahuah has already broken.$n$,$n$I am ordained to restrain the Leviathan, for unto me are subject the attack and menace of every single reptile.$n$,false),
(48719,'S','apocalypse-of-abraham',10,8,'apocalypse-of-abraham',10,8,$n$Isaiah 27:1 — *In that day Yahuah (LORD) with his sore and great and strong sword shall punish leviathan the piercing serpent, even leviathan that crooked serpent; and he shall slay the dragon that is in the sea.* The Leviathan subject to Jaoel's restraint (Apocalypse of Abraham 10:8) is the very dragon Yahuah judges.$n$,$n$I am ordained to restrain the Leviathan, for unto me are subject the attack and menace of every single reptile.$n$,false),
(48720,'S','apocalypse-of-abraham',10,7,'apocalypse-of-abraham',10,7,$n$Ezekiel 1:13 — *As for the likeness of the living creatures, their appearance was like burning coals of fire, and like the appearance of lamps: it went up and down among the living creatures; and the fire was bright, and out of the fire went forth lightning.* The living creatures of the Cherubim Jaoel restrains (Apocalypse of Abraham 10:7) are the fiery beasts of Ezekiel's chariot.$n$,$n$I am the one who hath been given to restrain, according to His commandment, the threatening attack of the living creatures of the Cherubim against one another, and to teach those who carry Him the song of the seventh hour of the night of man.$n$,false),
(48721,'S','apocalypse-of-abraham',10,11,'apocalypse-of-abraham',10,11,$n$Exodus 23:20 — *Behold, I send an Angel before thee, to keep thee in the way, and to bring thee into the place which I have prepared.* As that Angel brings Israel to the prepared place, Jaoel is sent to bring Abraham to the land prepared for him in Apocalypse of Abraham 10:11.$n$,$n$I have been sent to bless thee now, and the land which the Eternal One, whom thou hast invoked, hath prepared for thee, and for thy sake have I wended my way upon the earth.$n$,false),
(48722,'S','apocalypse-of-abraham',10,6,'apocalypse-of-abraham',10,6,$n$Exodus 23:21 — *Beware of him, and obey his voice, provoke him not; for he will not pardon your transgressions: for my name is in him.* Jaoel is a power by virtue of the ineffable Name dwelling in him (Apocalypse of Abraham 10:6) — the Name-bearing Angel of Exodus.$n$,$n$I am called Jaoel by Him who moveth that which existeth with me on the seventh expanse upon the firmament, a power in virtue of the ineffable Name that is dwelling in me.$n$,false),
(48723,'S','apocalypse-of-abraham',10,4,'apocalypse-of-abraham',10,4,$n$Isaiah 41:8 — *But thou, Yashar'el (Israel), art my servant, Jacob whom I have chosen, the seed of Abraham my friend.* The Creator who loveth Abraham (Apocalypse of Abraham 10:4) carries that love into the chosen seed of Israel.$n$,$n$For, lo, I have been sent to thee to strengthen thee and bless thee in the name of Elohim (God) who loveth thee — the Creator of the celestial and terrestrial.$n$,false),
(48724,'S','apocalypse-of-abraham',10,3,'apocalypse-of-abraham',10,3,$n$2 Chronicles 20:7 — *Art not thou our Elohim (God), who didst drive out the inhabitants of this land before thy people Yashar'el (Israel), and gavest it to the seed of Abraham thy friend for ever?* Jehoshaphat pleads the same friendship the angel speaks over Abraham in Apocalypse of Abraham 10:3.$n$,$n$And the angel came, whom He had sent to me, in the likeness of a man, and grasped me by my right hand, and set me up upon my feet, and said to me: "Stand up, Abraham, Friend of Elohim (God) who loveth thee; let not the trembling of man seize thee!$n$,false),
(48725,'S','apocalypse-of-abraham',10,3,'apocalypse-of-abraham',10,3,$n$James 2:23 — *And the scripture was fulfilled which saith, Abraham believed Elohim (God), and it was imputed unto him for righteousness: and he was called the Friend of Elohim (God).* The angel hails Abraham by the very name Scripture gives him in Apocalypse of Abraham 10:3.$n$,$n$And the angel came, whom He had sent to me, in the likeness of a man, and grasped me by my right hand, and set me up upon my feet, and said to me: "Stand up, Abraham, Friend of Elohim (God) who loveth thee; let not the trembling of man seize thee!$n$,false),
(48726,'S','apocalypse-of-abraham',11,6,'apocalypse-of-abraham',11,3,$n$Joshua 5:14 — *And he said, Nay; but as captain of the host of Yahuah (LORD) am I now come. And Joshua fell on his face to the earth, and did worship, and said unto him, What saith my lord unto his servant?* The captain of Yahuah's host who is worshipped by Joshua is the same Name-bearing angel Abraham follows with "Here am I, thy servant."$n$,$n$And I said: "Here am I, thy servant."$n$,false),
(48727,'S','apocalypse-of-abraham',11,6,'apocalypse-of-abraham',11,5,$n$Acts 7:2 — *And he said, Men, brethren, and fathers, hearken; The Elohim (God) of glory appeared unto our father Abraham, when he was in Mesopotamia, before he dwelt in Charran,* The same God of glory who called Abraham out of Mesopotamia now sends His Name-bearing angel to say "Come with me"$n$,$n$Come with me and I will go with thee, until the sacrifice, visible; but after the sacrifice, invisible for ever.$n$,false),
(48798,'S','apocalypse-of-abraham',16,4,'apocalypse-of-abraham',16,4,$n$Isaiah 41:10 — *Fear thou not; for I am with thee: be not dismayed; for I am thy Elohim (God): I will strengthen thee; yea, I will help thee; yea, I will uphold thee with the right hand of my righteousness.* The angel's exact words to Abraham in 16:4 — 'I am with thee, strengthening thee' — are the LORD's own covenant promise to Abraham's seed.$n$,$n$But let not thy spirit grow faint on account of the loud crying, for I am with thee, strengthening thee."$n$,false),
(48805,'S','apocalypse-of-abraham',17,14,'apocalypse-of-abraham',17,14,$n$Genesis 15:17 — *And it came to pass, that, when the sun went down, and it was dark, behold a smoking furnace, and a burning lamp that passed between those pieces.* The 'sacrifice which Thou hast prepared Thee through me' is the very covenant cutting of Genesis 15, where the fire passed between the pieces.$n$,$n$Accept my prayer, and be well-pleased with it, likewise also the sacrifice which Thou hast prepared Thee through me who sought Thee!$n$,false),
(48814,'S','apocalypse-of-abraham',17,8,'apocalypse-of-abraham',17,8,$n$Psalms 90:2 — *Before the mountains were brought forth, or ever thou hadst formed the earth and the world, even from everlasting to everlasting, thou art Elohim (God).* The 'Uncreate... Without father, without mother, unbegotten' One is the everlasting-to-everlasting Elohim of Moses.$n$,$n$Thou who art self-originated, incorruptible, spotless, Uncreate, immaculate, immortal, Self-complete, self-illuminating, Without father, without mother, unbegotten, Exalted, fiery One!$n$,false),
(48843,'S','apocalypse-of-abraham',19,6,'apocalypse-of-abraham',19,6,$n$*And I looked from the mountain in which I stood downwards to the sixth firmament, and saw there a multitude of angels, of pure spirit, without bodies, who carried out the commands of the fiery angels who were upon the eighth firmament, as I was standing suspended over them.* (Apocalypse of Abraham 19:6). *Who maketh his angels spirits; his ministers a flaming fire:* (Psalm 104:4). Abraham looks down and sees angels of pure spirit, without bodies, carrying out the commands of the fiery angels above them. The psalm says that He makes His angels spirits and His ministers a flaming fire. The two lines match in order: the spirits who do the work below, and the fiery ones who command them from above. Abraham sees what the psalm says.$n$,$n$And I looked from the mountain in which I stood downwards to the sixth firmament, and saw there a multitude of angels, of pure spirit, without bodies, who carried out the commands of the fiery angels who were upon the eighth firmament, as I was standing suspended over them.$n$,true),
(48848,'S','apocalypse-of-abraham',19,1,'apocalypse-of-abraham',19,1,$n$*And a voice came to me out of the midst of the fire, saying: "Abraham, Abraham!"* (Apocalypse of Abraham 19:1). *And the angel of Yahuah (LORD) appeared unto him in a flame of fire out of the midst of a bush: and he looked, and, behold, the bush burned with fire, and the bush was not consumed.* (Exodus 3:2). Abraham is called by name out of the midst of fire. In Exodus the angel of Yahuah (the LORD) appears to Moses in a flame of fire out of the midst of a bush that burns and is not consumed. In both, the fire is the place from which the call comes, not a danger to the one being called. Yahuah (the LORD) meets the man He is calling in the fire.$n$,$n$And a voice came to me out of the midst of the fire, saying: "Abraham, Abraham!"$n$,true),
(48898,'S','apocalypse-of-abraham',23,6,'apocalypse-of-abraham',23,6,$n$1 Enoch 10:8 — *And the whole earth has been corrupted through the works that were taught by Azâzêl: to him ascribe all sin.'* Abraham's word that Azazel is 'their beginning on the way to perdition' matches Enoch's verdict that to Azazel is ascribed all the corruption of the earth.$n$,$n$And He said: "This is the human world, this is Adam, and this is their desire upon the earth, this is Eve; but he who is between them representeth ungodliness, their beginning on the way to perdition, even Azazel."$n$,false),
(48960,'S','apocalypse-of-abraham',29,18,'apocalypse-of-abraham',29,18,$n$Matthew 24:31 — *And he shall send his angels with a great sound of a trumpet, and they shall gather together his elect from the four winds, from one end of heaven to the other.* The hastening of the kept seed to the prepared place is the gathering of the elect by the angels at the great trumpet (Apocalypse of Abraham 29:18).$n$,$n$And then shall righteous men of thy seed be left, in the number which is kept secret by me, hastening in the glory of My Name to the place prepared beforehand for them, which thou sawest devastated in the picture; and they shall live and be established through sacrifices and gifts of righteousness and truth in the Age of the righteous, and shall rejoice in Me continually; and they shall destroy those who have destroyed them, and shall insult those who have insulted them.$n$,false),
(48961,'S','apocalypse-of-abraham',29,18,'apocalypse-of-abraham',29,18,$n$Isaiah 11:11 — *And it shall come to pass in that day, that Yahuah (Lord) shall set his hand again the second time to recover the remnant of his people, which shall be left, from Assyria, and from Egypt, and from Pathros, and from Cush, and from Elam, and from Shinar, and from Hamath, and from the islands of the sea.* The righteous of the seed left in the secret number are the two-house remnant the LORD recovers the second time (Apocalypse of Abraham 29:18).$n$,$n$And then shall righteous men of thy seed be left, in the number which is kept secret by me, hastening in the glory of My Name to the place prepared beforehand for them, which thou sawest devastated in the picture; and they shall live and be established through sacrifices and gifts of righteousness and truth in the Age of the righteous, and shall rejoice in Me continually; and they shall destroy those who have destroyed them, and shall insult those who have insulted them.$n$,false),
(48962,'S','apocalypse-of-abraham',29,18,'apocalypse-of-abraham',29,18,$n$Isaiah 27:13 — *And it shall come to pass in that day, that the great trumpet shall be blown, and they shall come which were ready to perish in the land of Assyria, and the outcasts in the land of Egypt, and shall worship Yahuah (LORD) in the holy mount at Jerusalem.* The righteous of Abraham's seed left and hastening to the prepared place are the outcasts gathered at the great trumpet to worship in the holy mount (Apocalypse of Abraham 29:18).$n$,$n$And then shall righteous men of thy seed be left, in the number which is kept secret by me, hastening in the glory of My Name to the place prepared beforehand for them, which thou sawest devastated in the picture; and they shall live and be established through sacrifices and gifts of righteousness and truth in the Age of the righteous, and shall rejoice in Me continually; and they shall destroy those who have destroyed them, and shall insult those who have insulted them.$n$,false),
(48963,'S','apocalypse-of-abraham',29,15,'apocalypse-of-abraham',29,15,$n$Joel 3:2 — *I will also gather all nations, and will bring them down into the valley of Jehoshaphat, and will plead with them there for my people and for my heritage Yashar'el (Israel), whom they have scattered among the nations, and parted my land.* The judgment that comes upon the lawless heathen through the separated seed is the LORD's pleading with the nations for His scattered heritage (Apocalypse of Abraham 29:15).$n$,$n$Before the Age of the righteous beginneth to grow, my judgement shall come upon the lawless heathen through the people of thy seed who have been separated for me.$n$,false),
(48964,'S','apocalypse-of-abraham',29,14,'apocalypse-of-abraham',29,14,$n$Matthew 24:22 — *And except those days should be shortened, there should no flesh be saved: but for the elect's sake those days shall be shortened.* The shortening of the Age of ungodliness for the sake of those who worshipped of Abraham's seed is the very shortening of days for the elect's sake (Apocalypse of Abraham 29:14).$n$,$n$He, however, is testing those who have worshipped him of thy seed, in that twelfth hour of the End, with a view to shortening the Age of ungodliness.$n$,false),
(48965,'S','apocalypse-of-abraham',29,12,'apocalypse-of-abraham',29,12,$n$Isaiah 11:10 — *And in that day there shall be a root of Jesse, which shall stand for an ensign of the people; to it shall the Gentiles seek: and his rest shall be glorious.* The man set up from Abraham's generation whom many of the heathen follow is the ensign of Jesse to whom the Gentiles seek (Apocalypse of Abraham 29:12).$n$,$n$But in the twelfth year of my final Age I will set up this man from thy generation, whom thou sawest issue from my people; this one all will follow, and such as are called by me will join, even those who change in their counsels.$n$,false),
(48966,'S','apocalypse-of-abraham',29,13,'apocalypse-of-abraham',29,13,$n$Deuteronomy 30:15 — *See, I have set before thee this day life and good, and death and evil.* The vision's two sides, the right and the left, set the same two ways before the seed that Moses set before Israel (Apocalypse of Abraham 29:13).$n$,$n$And those whom thou sawest emerge from the left side of the picture — the meaning is: there shall be many from the heathen who set their hopes upon him; and as for those whom thou sawest from thy seed on the right side, some insulting and striking, others worshipping him — many of them shall be offended at him.$n$,false),
(48967,'S','apocalypse-of-abraham',29,13,'apocalypse-of-abraham',29,13,$n$Genesis 25:23 — *And Yahuah (LORD) said unto her, Two nations are in thy womb, and two manner of people shall be separated from thy bowels; and the one people shall be stronger than the other people; and the elder shall serve the younger.* The left side of the heathen and the right side of Abraham's seed are the two manner of people divided since the womb of Rebekah (Apocalypse of Abraham 29:13).$n$,$n$And those whom thou sawest emerge from the left side of the picture — the meaning is: there shall be many from the heathen who set their hopes upon him; and as for those whom thou sawest from thy seed on the right side, some insulting and striking, others worshipping him — many of them shall be offended at him.$n$,false),
(48968,'S','apocalypse-of-abraham',29,7,'apocalypse-of-abraham',29,7,$n$Jude 1:6 — *And the angels which kept not their first estate, but left their own habitation, he hath reserved in everlasting chains under darkness unto the judgment of the great day.* Azazel's false worship is the homage of a fallen angel already reserved in chains of darkness for the great day of judgment (Apocalypse of Abraham 29:7).$n$,$n$And I saw how these worshipped him, and Azazel ran and worshipped him, and, having kissed his face, he turned and stood behind him.$n$,false),
(48969,'S','apocalypse-of-abraham',29,7,'apocalypse-of-abraham',29,7,$n$Leviticus 16:10 — *But the goat, on which the lot fell to be the scapegoat, shall be presented alive before Yahuah (LORD), to make an atonement with him, and to let him go for a scapegoat into the wilderness.* Azazel, who turns and stands behind the man, bears the name of the scapegoat-lot sent out into the wilderness on the Day of Atonement (Apocalypse of Abraham 29:7).$n$,$n$And I saw how these worshipped him, and Azazel ran and worshipped him, and, having kissed his face, he turned and stood behind him.$n$,false),
(48970,'S','apocalypse-of-abraham',29,7,'apocalypse-of-abraham',29,7,$n$1 Enoch 10:8 — *And the whole earth has been corrupted through the works that were taught by Azâzêl: to him ascribe all sin.'* The Azazel whose false homage Abraham sees is the one to whom all sin is ascribed, the corrupter of the whole earth (Apocalypse of Abraham 29:7).$n$,$n$And I saw how these worshipped him, and Azazel ran and worshipped him, and, having kissed his face, he turned and stood behind him.$n$,false),
(48971,'S','apocalypse-of-abraham',29,7,'apocalypse-of-abraham',29,7,$n$1 Enoch 10:4 — *And again Yahuah (God) said to Raphael: 'Bind Azâzêl hand and foot, and cast him into the darkness: and make an opening in the desert, which is in Dûdâêl, and cast him therein.* The Azazel who runs and kisses the man's face in Abraham's vision is the same fallen chief whom the LORD bound and cast into the desert-darkness for judgment (Apocalypse of Abraham 29:7).$n$,$n$And I saw how these worshipped him, and Azazel ran and worshipped him, and, having kissed his face, he turned and stood behind him.$n$,false),
(48972,'S','apocalypse-of-abraham',29,13,'apocalypse-of-abraham',29,13,$n$Matthew 24:10 — *And then shall many be offended, and shall betray one another, and shall hate one another.* That many of Abraham's own seed shall be offended at the man matches Messiah's word that in the last days many shall be offended (Apocalypse of Abraham 29:13).$n$,$n$And those whom thou sawest emerge from the left side of the picture — the meaning is: there shall be many from the heathen who set their hopes upon him; and as for those whom thou sawest from thy seed on the right side, some insulting and striking, others worshipping him — many of them shall be offended at him.$n$,false),
(48973,'S','apocalypse-of-abraham',29,6,'apocalypse-of-abraham',29,6,$n$Psalm 22:7 — *All they that see me laugh me to scorn: they shoot out the lip, they shake the head, saying.* The insulting and striking that Abraham watches fall on the man is the very scorn of the watching crowd in the Psalm of the pierced one (Apocalypse of Abraham 29:6).$n$,$n$And while I still looked, there came out from the right side many, and some insulted that man, while some struck him; others, however, worshipped him.$n$,false),
(48974,'S','apocalypse-of-abraham',29,6,'apocalypse-of-abraham',29,6,$n$Isaiah 53:3 — *He is despised and rejected of men; a man of sorrows, and acquainted with grief: and we hid as it were our faces from him; he was despised, and we esteemed him not.* Abraham's vision of the man insulted and struck by his own is the same despised and rejected one Isaiah set before Israel's seed (Apocalypse of Abraham 29:6).$n$,$n$And while I still looked, there came out from the right side many, and some insulted that man, while some struck him; others, however, worshipped him.$n$,false),
(48975,'S','apocalypse-of-abraham',29,3,'apocalypse-of-abraham',29,3,$n$Daniel 7:14 — *And there was given him dominion, and glory, and a kingdom, that all people, nations, and languages, should serve him: his dominion is an everlasting dominion, which shall not pass away, and his kingdom that which shall not be destroyed.* The end of the twelve-hour Age is the handing of the everlasting, indestructible kingdom to the Son of Adam, the rule the heathen Age could only counterfeit for a season (Apocalypse of Abraham 29:3).$n$,$n$And He said: "Twelve years have I ordained of this ungodly Age to rule among the heathen and in thy seed; and until the end of the times it shall be as thou sawest.$n$,false),
(48976,'S','apocalypse-of-abraham',29,3,'apocalypse-of-abraham',29,3,$n$Daniel 7:12 — *As concerning the rest of the beasts, they had their dominion taken away: yet their lives were prolonged for a season and time.* As the ungodly Age is ordained to rule only for a measured span among the heathen, so Daniel's beasts hold dominion only for a season and time before it is taken away (Apocalypse of Abraham 29:3).$n$,$n$And He said: "Twelve years have I ordained of this ungodly Age to rule among the heathen and in thy seed; and until the end of the times it shall be as thou sawest.$n$,false);
CREATE TEMP TABLE _s463ebm (thread_id INT, xid INT, new_note TEXT) ON COMMIT DROP;
INSERT INTO _s463ebm VALUES
(1952,12949,$n$Apocalypse of Abraham 18:4 — *of a lion, of a man, of an ox, of an eagle: four heads were upon their bodies.* Abraham's four faced creatures with six wings are the beasts around the throne in Revelation 4:8.$n$),
(11819,48848,$n$Apocalypse of Abraham 19:1 — *a voice came to me out of the midst of the fire, saying.* The voice calling Abraham out of the fire is the fire from which Moses was called at the bush in Exodus 3:2.$n$),
(11821,48843,$n$Apocalypse of Abraham 19:6 — *angels, of pure spirit, without bodies, who carried out the commands of the fiery angels.* The bodiless spirits serving fiery angels are the spirits and flaming ministers of Psalm 104:4.$n$),
(11777,48700,$n$Romans 4:17 — *(As it is written, I have made thee a father of many nations,) before him whom he believed, even Elohim (God), who quickeneth the dead, and calleth those things which be not as though they were.* The ages which 'shall come to pass' shewn Abraham in 9:7 are seen by the same faith that calls the not-yet as though it already were.$n$),
(11777,48702,$n$Genesis 15:13 — *And he said unto Abram, Know of a surety that thy seed shall be a stranger in a land that is not theirs, and shall serve them; and they shall afflict them four hundred years.* The 'ages (to come)' laid before Abraham in 9:6 are the very foretelling joined to the Genesis covenant — what shall come to pass upon the seed.$n$),
(11787,48727,$n$Acts 7:2 — *And he said, Men, brethren, and fathers, hearken; The Elohim (God) of glory appeared unto our father Abraham, when he was in Mesopotamia, before he dwelt in Charran,* The same God of glory who called Abraham out of Mesopotamia now sends His Name-bearing angel to say "Come with me"$n$),
(11807,48798,$n$Isaiah 41:10 — *Fear thou not; for I am with thee: be not dismayed; for I am thy Elohim (God): I will strengthen thee; yea, I will help thee; yea, I will uphold thee with the right hand of my righteousness.* The angel's exact words to Abraham in 16:4 — 'I am with thee, strengthening thee' — are the LORD's own covenant promise to Abraham's seed.$n$),
(11813,48805,$n$Genesis 15:17 — *And it came to pass, that, when the sun went down, and it was dark, behold a smoking furnace, and a burning lamp that passed between those pieces.* The 'sacrifice which Thou hast prepared Thee through me' is the very covenant cutting of Genesis 15, where the fire passed between the pieces.$n$),
(11810,48814,$n$Psalms 90:2 — *Before the mountains were brought forth, or ever thou hadst formed the earth and the world, even from everlasting to everlasting, thou art Elohim (God).* The 'Uncreate... Without father, without mother, unbegotten' One is the everlasting-to-everlasting Elohim of Moses.$n$),
(11836,48898,$n$1 Enoch 10:8 — *And the whole earth has been corrupted through the works that were taught by Azâzêl: to him ascribe all sin.'* Abraham's word that Azazel is 'their beginning on the way to perdition' matches Enoch's verdict that to Azazel is ascribed all the corruption of the earth.$n$),
(11783,48711,$n$Genesis 12:1 — *Now Yahuah (LORD) had said unto Abram, Get thee out of thy country, and from thy kindred, and from thy father's house, unto a land that I will shew thee.* The land the Eternal One hath prepared, for which Jaoel comes (Apocalypse of Abraham 10:11), is the land of the first calling-out.$n$),
(11783,48712,$n$Genesis 15:5 — *And he brought him forth abroad, and said, Look now toward heaven, and tell the stars, if thou be able to number them: and he said unto him, So shall thy seed be.* The generation prepared to spring from Abraham (Apocalypse of Abraham 10:16) is the innumerable seed shown as the stars.$n$),
(11783,48713,$n$Genesis 15:9 — *And he said unto him, Take me an heifer of three years old, and a she goat of three years old, and a ram of three years old, and a turtledove, and a young pigeon.* The sacrifices Jaoel commands Abraham to fulfil (Apocalypse of Abraham 10:15) are the exact heifer, goat, ram, turtledove and pigeon of the Genesis covenant.$n$),
(11782,48714,$n$1 Enoch 10:8 — *And the whole earth has been corrupted through the works that were taught by Azâzêl: to him ascribe all sin.* The corrupting reverence for dead idols burned away in Apocalypse of Abraham 10:10 is the same Azazel-system whose works defile the earth.$n$),
(11782,48715,$n$Isaiah 44:15 — *Then shall it be for a man to burn: for he will take thereof, and warm himself; yea, he kindleth it, and baketh bread; yea, he maketh a god, and worshippeth it; he maketh it a graven image, and falleth down thereto.* The wood that becomes a worshipped god is fit only for the fire that consumes the idol-house in Apocalypse of Abraham 10:10.$n$),
(11782,48716,$n$Isaiah 44:9 — *They that make a graven image are all of them vanity; and their delectable things shall not profit; and they are their own witnesses; they see not, nor know; that they may be ashamed.* The dead idols Terah reveres (Apocalypse of Abraham 10:10) are the very vanity Isaiah exposes.$n$),
(11782,48717,$n$Joshua 24:2 — *And Joshua said unto all the people, Thus saith Yahuah Elohim (the LORD God) of Yashar'el (Israel), Your fathers dwelt on the other side of the flood in old time, even Terah, the father of Abraham, and the father of Nachor: and they served other gods.* Terah's idolatrous house, marked for burning in Apocalypse of Abraham 10:10, is named outright in Israel's own record.$n$),
(11781,48718,$n$Psalm 74:14 — *Thou brakest the heads of leviathan in pieces, and gavest him to be meat to the people inhabiting the wilderness.* The menace of Leviathan that bows to His command (Apocalypse of Abraham 10:8) is the head Yahuah has already broken.$n$),
(11781,48719,$n$Isaiah 27:1 — *In that day Yahuah (LORD) with his sore and great and strong sword shall punish leviathan the piercing serpent, even leviathan that crooked serpent; and he shall slay the dragon that is in the sea.* The Leviathan subject to Jaoel's restraint (Apocalypse of Abraham 10:8) is the very dragon Yahuah judges.$n$),
(11781,48720,$n$Ezekiel 1:13 — *As for the likeness of the living creatures, their appearance was like burning coals of fire, and like the appearance of lamps: it went up and down among the living creatures; and the fire was bright, and out of the fire went forth lightning.* The living creatures of the Cherubim Jaoel restrains (Apocalypse of Abraham 10:7) are the fiery beasts of Ezekiel's chariot.$n$),
(11780,48721,$n$Exodus 23:20 — *Behold, I send an Angel before thee, to keep thee in the way, and to bring thee into the place which I have prepared.* As that Angel brings Israel to the prepared place, Jaoel is sent to bring Abraham to the land prepared for him in Apocalypse of Abraham 10:11.$n$),
(11780,48722,$n$Exodus 23:21 — *Beware of him, and obey his voice, provoke him not; for he will not pardon your transgressions: for my name is in him.* Jaoel is a power by virtue of the ineffable Name dwelling in him (Apocalypse of Abraham 10:6) — the Name-bearing Angel of Exodus.$n$),
(11779,48723,$n$Isaiah 41:8 — *But thou, Yashar'el (Israel), art my servant, Jacob whom I have chosen, the seed of Abraham my friend.* The Creator who loveth Abraham (Apocalypse of Abraham 10:4) carries that love into the chosen seed of Israel.$n$),
(11779,48724,$n$2 Chronicles 20:7 — *Art not thou our Elohim (God), who didst drive out the inhabitants of this land before thy people Yashar'el (Israel), and gavest it to the seed of Abraham thy friend for ever?* Jehoshaphat pleads the same friendship the angel speaks over Abraham in Apocalypse of Abraham 10:3.$n$),
(11779,48725,$n$James 2:23 — *And the scripture was fulfilled which saith, Abraham believed Elohim (God), and it was imputed unto him for righteousness: and he was called the Friend of Elohim (God).* The angel hails Abraham by the very name Scripture gives him in Apocalypse of Abraham 10:3.$n$),
(11861,48960,$n$Matthew 24:31 — *And he shall send his angels with a great sound of a trumpet, and they shall gather together his elect from the four winds, from one end of heaven to the other.* The hastening of the kept seed to the prepared place is the gathering of the elect by the angels at the great trumpet (Apocalypse of Abraham 29:18).$n$),
(11861,48961,$n$Isaiah 11:11 — *And it shall come to pass in that day, that Yahuah (Lord) shall set his hand again the second time to recover the remnant of his people, which shall be left, from Assyria, and from Egypt, and from Pathros, and from Cush, and from Elam, and from Shinar, and from Hamath, and from the islands of the sea.* The righteous of the seed left in the secret number are the two-house remnant the LORD recovers the second time (Apocalypse of Abraham 29:18).$n$),
(11861,48962,$n$Isaiah 27:13 — *And it shall come to pass in that day, that the great trumpet shall be blown, and they shall come which were ready to perish in the land of Assyria, and the outcasts in the land of Egypt, and shall worship Yahuah (LORD) in the holy mount at Jerusalem.* The righteous of Abraham's seed left and hastening to the prepared place are the outcasts gathered at the great trumpet to worship in the holy mount (Apocalypse of Abraham 29:18).$n$),
(11860,48963,$n$Joel 3:2 — *I will also gather all nations, and will bring them down into the valley of Jehoshaphat, and will plead with them there for my people and for my heritage Yashar'el (Israel), whom they have scattered among the nations, and parted my land.* The judgment that comes upon the lawless heathen through the separated seed is the LORD's pleading with the nations for His scattered heritage (Apocalypse of Abraham 29:15).$n$),
(11860,48964,$n$Matthew 24:22 — *And except those days should be shortened, there should no flesh be saved: but for the elect's sake those days shall be shortened.* The shortening of the Age of ungodliness for the sake of those who worshipped of Abraham's seed is the very shortening of days for the elect's sake (Apocalypse of Abraham 29:14).$n$),
(11859,48965,$n$Isaiah 11:10 — *And in that day there shall be a root of Jesse, which shall stand for an ensign of the people; to it shall the Gentiles seek: and his rest shall be glorious.* The man set up from Abraham's generation whom many of the heathen follow is the ensign of Jesse to whom the Gentiles seek (Apocalypse of Abraham 29:12).$n$),
(11859,48966,$n$Deuteronomy 30:15 — *See, I have set before thee this day life and good, and death and evil.* The vision's two sides, the right and the left, set the same two ways before the seed that Moses set before Israel (Apocalypse of Abraham 29:13).$n$),
(11859,48967,$n$Genesis 25:23 — *And Yahuah (LORD) said unto her, Two nations are in thy womb, and two manner of people shall be separated from thy bowels; and the one people shall be stronger than the other people; and the elder shall serve the younger.* The left side of the heathen and the right side of Abraham's seed are the two manner of people divided since the womb of Rebekah (Apocalypse of Abraham 29:13).$n$),
(11858,48968,$n$Jude 1:6 — *And the angels which kept not their first estate, but left their own habitation, he hath reserved in everlasting chains under darkness unto the judgment of the great day.* Azazel's false worship is the homage of a fallen angel already reserved in chains of darkness for the great day of judgment (Apocalypse of Abraham 29:7).$n$),
(11858,48969,$n$Leviticus 16:10 — *But the goat, on which the lot fell to be the scapegoat, shall be presented alive before Yahuah (LORD), to make an atonement with him, and to let him go for a scapegoat into the wilderness.* Azazel, who turns and stands behind the man, bears the name of the scapegoat-lot sent out into the wilderness on the Day of Atonement (Apocalypse of Abraham 29:7).$n$),
(11858,48970,$n$1 Enoch 10:8 — *And the whole earth has been corrupted through the works that were taught by Azâzêl: to him ascribe all sin.'* The Azazel whose false homage Abraham sees is the one to whom all sin is ascribed, the corrupter of the whole earth (Apocalypse of Abraham 29:7).$n$),
(11858,48971,$n$1 Enoch 10:4 — *And again Yahuah (God) said to Raphael: 'Bind Azâzêl hand and foot, and cast him into the darkness: and make an opening in the desert, which is in Dûdâêl, and cast him therein.* The Azazel who runs and kisses the man's face in Abraham's vision is the same fallen chief whom the LORD bound and cast into the desert-darkness for judgment (Apocalypse of Abraham 29:7).$n$),
(11857,48972,$n$Matthew 24:10 — *And then shall many be offended, and shall betray one another, and shall hate one another.* That many of Abraham's own seed shall be offended at the man matches Messiah's word that in the last days many shall be offended (Apocalypse of Abraham 29:13).$n$),
(11857,48973,$n$Psalm 22:7 — *All they that see me laugh me to scorn: they shoot out the lip, they shake the head, saying.* The insulting and striking that Abraham watches fall on the man is the very scorn of the watching crowd in the Psalm of the pierced one (Apocalypse of Abraham 29:6).$n$),
(11857,48974,$n$Isaiah 53:3 — *He is despised and rejected of men; a man of sorrows, and acquainted with grief: and we hid as it were our faces from him; he was despised, and we esteemed him not.* Abraham's vision of the man insulted and struck by his own is the same despised and rejected one Isaiah set before Israel's seed (Apocalypse of Abraham 29:6).$n$),
(11856,48975,$n$Daniel 7:14 — *And there was given him dominion, and glory, and a kingdom, that all people, nations, and languages, should serve him: his dominion is an everlasting dominion, which shall not pass away, and his kingdom that which shall not be destroyed.* The end of the twelve-hour Age is the handing of the everlasting, indestructible kingdom to the Son of Adam, the rule the heathen Age could only counterfeit for a season (Apocalypse of Abraham 29:3).$n$),
(11856,48976,$n$Daniel 7:12 — *As concerning the rest of the beasts, they had their dominion taken away: yet their lives were prolonged for a season and time.* As the ungodly Age is ordained to rule only for a measured span among the heathen, so Daniel's beasts hold dominion only for a season and time before it is taken away (Apocalypse of Abraham 29:3).$n$);
CREATE TEMP TABLE _s463ebs (thread_id INT, old_summary TEXT, new_summary TEXT) ON COMMIT DROP;
INSERT INTO _s463ebs VALUES
(11787,$n$The angel's whole errand is to bring Abraham to the offering: *Come with me and I will go with thee, until the sacrifice, visible; but after the sacrifice, invisible for ever. Be of good cheer, and come!* (Apocalypse of Abraham 11:5-6). It ain't new — this is the road to Genesis 15, the cutting of the covenant: *And he said unto him, Take me an heifer of three years old, and a she goat of three years old, and a ram of three years old, and a turtledove, and a young pigeon.* (Genesis 15:9), and the glory that passed between the pieces: *And it came to pass, that, when the sun went down, and it was dark, behold a smoking furnace, and a burning lamp that passed between those pieces.* (Genesis 15:17) — the visible Presence at the sacrifice. The God of glory had already called Abraham out by this same summons: *The Elohim (God) of glory appeared unto our father Abraham, when he was in Mesopotamia, before he dwelt in Charran,* (Acts 7:2) saying *Get thee out of thy country, and from thy kindred, and come into the land which I shall shew thee.* (Acts 7:3). And the man-with-the-sword who met Joshua is the same captain who is worshipped: *And he said, Nay; but as captain of the host of Yahuah (LORD) am I now come. And Joshua fell on his face to the earth, and did worship...* (Joshua 5:14) — the angel who bears the Name, leading the elect to the covenant.$n$,$n$The angel's whole errand is to bring Abraham to the offering: *Come with me and I will go with thee, until the sacrifice, visible; but after the sacrifice, invisible for ever. Be of good cheer, and come!* (Apocalypse of Abraham 11:5–6). It ain't new — this is the road to Genesis 15, the cutting of the covenant: *And he said unto him, Take me an heifer of three years old, and a she goat of three years old, and a ram of three years old, and a turtledove, and a young pigeon.* (Genesis 15:9), and the glory that passed between the pieces: *And it came to pass, that, when the sun went down, and it was dark, behold a smoking furnace, and a burning lamp that passed between those pieces.* (Genesis 15:17) — the visible Presence at the sacrifice. The Elohim (God) of glory had already called Abraham out by this same summons: *The Elohim (God) of glory appeared unto our father Abraham, when he was in Mesopotamia, before he dwelt in Charran,* (Acts 7:2) saying *Get thee out of thy country, and from thy kindred, and come into the land which I shall shew thee.* (Acts 7:3). And the man with the sword who met Joshua is the same captain who is worshipped: *And he said, Nay; but as captain of the host of Yahuah (LORD) am I now come. And Joshua fell on his face to the earth, and did worship...* (Joshua 5:14) — the angel who bears the Name, leading the elect to the covenant.$n$),
(11794,$n$The bird that speaks is unmasked: *And he said: "This is ungodliness, this is Azazel."* (Apocalypse of Abraham 13:7) — *And he said to it: "Disgrace upon thee, Azazel!"* (Apocalypse of Abraham 13:8) It ain't new — Azazel is the lot of the scapegoat in the Torah's day of atonement, the goat that bears uncleanness away into the wilderness while the LORD's lot is offered for the people: *And Aaron shall cast lots upon the two goats; one lot for Yahuah (LORD), and the other lot for the scapegoat.* (Leviticus 16:8) — *But the goat, on which the lot fell to be the scapegoat, shall be presented alive before Yahuah (LORD), to make an atonement with him, and to let him go for a scapegoat into the wilderness.* (Leviticus 16:10) And the Watchers' apparatus names him plainly — the corrupter of the earth to whom all sin is ascribed: *And the whole earth has been corrupted through the works that were taught by Azâzêl: to him ascribe all sin.* (1 Enoch 8:1 / 1 Enoch 10:8). Two lots, two peoples; the unclean is sent away, the righteous is kept.$n$,$n$The bird that speaks is unmasked: *And he said: "This is ungodliness, this is Azazel."* (Apocalypse of Abraham 13:7) — *And he said to it: "Disgrace upon thee, Azazel!"* (Apocalypse of Abraham 13:8) It ain't new — Azazel is the lot of the scapegoat in the Torah's day of atonement, the goat that bears uncleanness away into the wilderness while Yahuah's lot is offered for the people: *And Aaron shall cast lots upon the two goats; one lot for Yahuah (LORD), and the other lot for the scapegoat.* (Leviticus 16:8) — *But the goat, on which the lot fell to be the scapegoat, shall be presented alive before Yahuah (LORD), to make an atonement with him, and to let him go for a scapegoat into the wilderness.* (Leviticus 16:10) And 1 Enoch, the book of the Watchers, names him plainly — the corrupter of the earth to whom all sin is ascribed: *And the whole earth has been corrupted through the works that were taught by Azâzêl: to him ascribe all sin.* (1 Enoch 10:8). Two lots, two peoples; the unclean is sent away, the righteous is kept.$n$),
(11795,$n$The angel pronounces the two dwelling-places: *For Abraham's lot is in heaven, but thine upon the earth.* (Apocalypse of Abraham 13:9) — *Because thou hast chosen and loved this for the dwelling-place of thine uncleanness, therefore the eternal mighty Yahuah (Lord) made thee a dweller upon the earth...* (Apocalypse of Abraham 13:10) It ain't new — this is the fallen one cast down out of the heights to the earth. The Watchers' apparatus binds and casts Azazel into the desert until the judgment: *And again Yahuah (God) said to Raphael: 'Bind Azâzêl hand and foot, and cast him into the darkness: and make an opening in the desert, which is in Dûdâêl, and cast him therein.* (1 Enoch 10:4) The angels that kept not their first estate are reserved in chains: *And the angels which kept not their first estate, but left their own habitation, he hath reserved in everlasting chains under darkness unto the judgment of the great day.* (Jude 1:6) — and the great dragon and his angels are flung to the earth: *And the great dragon was cast out, that old serpent, called the Devil, and Satan, which deceiveth the whole world: he was cast out into the earth, and his angels were cast out with him.* (Revelation 12:9) The adversary's reach is the dust; Abraham's portion is above.$n$,$n$The angel pronounces the two dwelling places: *For Abraham's lot is in heaven, but thine upon the earth.* (Apocalypse of Abraham 13:9) — *Because thou hast chosen and loved this for the dwelling-place of thine uncleanness, therefore the eternal mighty Yahuah (Lord) made thee a dweller upon the earth...* (Apocalypse of Abraham 13:10) It ain't new — this is the fallen one cast down out of the heights to the earth. 1 Enoch, the book of the Watchers, binds and casts Azazel into the desert until the judgment: *And again Yahuah (God) said to Raphael: 'Bind Azâzêl hand and foot, and cast him into the darkness: and make an opening in the desert, which is in Dûdâêl, and cast him therein.* (1 Enoch 10:4) The angels that kept not their first estate are reserved in chains: *And the angels which kept not their first estate, but left their own habitation, he hath reserved in everlasting chains under darkness unto the judgment of the great day.* (Jude 1:6) — and the great dragon and his angels are flung to the earth: *And the great dragon was cast out, that old serpent, called the Devil, and Satan, which deceiveth the whole world: he was cast out into the earth, and his angels were cast out with him.* (Revelation 12:9) The adversary's reach is the dust; Abraham's portion is above.$n$),
(11859,$n$The picture is divided: a man going out *from the left side of the heathen* drawing the hosts of the nations, and the seed of Abraham *on the right side*. The Eternal interprets: *And those whom thou sawest emerge from the left side of the picture — the meaning is: there shall be many from the heathen who set their hopes upon him.* It ain't new — the two peoples were divided in Rebekah's womb: *And Yahuah (LORD) said unto her, Two nations are in thy womb, and two manner of people shall be separated from thy bowels; and the one people shall be stronger than the other people; and the elder shall serve the younger* (Genesis 25:23). The right hand is the place of the elect at the gathering: the Son of Adam *shall set the sheep on his right hand, but the goats on the left* is Yoshi's same two-ways set before the seed by Moses — *See, I have set before thee this day life and good, and death and evil* (Deuteronomy 30:15). This is election of Abraham's seed, the heathen brought in to set their hope upon the one issued from that seed — not a people replacing Israel, but the nations grafted to the right side.$n$,$n$The picture is divided: a man going out *from the left side of the heathen* drawing the hosts of the nations, and the seed of Abraham *on the right side*. The Eternal interprets: *And those whom thou sawest emerge from the left side of the picture — the meaning is: there shall be many from the heathen who set their hopes upon him* (Apocalypse of Abraham 29:13). It ain't new — the two peoples were divided in Rebekah's womb: *And Yahuah (LORD) said unto her, Two nations are in thy womb, and two manner of people shall be separated from thy bowels; and the one people shall be stronger than the other people; and the elder shall serve the younger* (Genesis 25:23). The right hand is the place of the elect at the gathering: the Son of Adam *shall set the sheep on his right hand, but the goats on the left* (Matthew 25:33), the same two ways Moses set before the seed: *See, I have set before thee this day life and good, and death and evil* (Deuteronomy 30:15). This is election of Abraham's seed: those who set their hope upon the one issued from that seed are the scattered sheep hearing the Shepherd, because they were sheep before they heard — not a people replacing Yashar'el (Israel), and no outsiders grafted onto the right side.$n$),
(11823,$n$The Eternal Mighty One lifts Abraham above the firmament and sets him the same charge given at the covenant of the pieces: *"Consider from above the stars which are beneath thee, and number them for me, and make known to me their number."* (Apocalypse of Abraham 20:3) — *"As the number of the stars and their power, so will I make thy seed a nation and a people, set apart for me..."* (20:6). It ain't new: this is Genesis 15 carried up into heaven. There the same voice *brought him forth abroad, and said, Look now toward heaven, and tell the stars, if thou be able to number them: and he said unto him, So shall thy seed be* (Genesis 15:5). The oath was doubled at the binding — *in multiplying I will multiply thy seed as the stars of the heaven, and as the sand which is upon the sea shore* (Genesis 22:17), and the Besorah testifies it came to pass: *there sprang there even of one, and him as good as dead, so many as the stars of the sky in multitude* (Hebrews 11:12). Sha'ul names it the seed-promise believed against hope — *according to that which was spoken, So shall thy seed be* (Romans 4:18).$n$,$n$The Eternal Mighty One lifts Abraham above the firmament and sets him the same charge given at the covenant of the pieces: *"Consider from above the stars which are beneath thee, and number them for me, and make known to me their number."* (Apocalypse of Abraham 20:3) — *"As the number of the stars and their power, so will I make thy seed a nation and a people, set apart for me..."* (20:6). It ain't new: this is Genesis 15 carried up into heaven. There the same voice *brought him forth abroad, and said, Look now toward heaven, and tell the stars, if thou be able to number them: and he said unto him, So shall thy seed be* (Genesis 15:5). The oath was doubled at the binding — *in multiplying I will multiply thy seed as the stars of the heaven, and as the sand which is upon the sea shore* (Genesis 22:17), and the Besorah testifies it came to pass: *Therefore sprang there even of one, and him as good as dead, so many as the stars of the sky in multitude* (Hebrews 11:12). Sha'ul names it the seed-promise believed against hope — *according to that which was spoken, So shall thy seed be* (Romans 4:18).$n$);
CREATE TEMP VIEW _s463ebv AS
  SELECT v.id, e.slug es, b.slug bs, c.chapter_number ch, v.verse_number vn, v.text FROM verses v
    JOIN chapters c ON c.id=v.chapter_id JOIN books b ON b.id=c.book_id JOIN editions e ON e.id=b.edition_id;

DO $fix$
DECLARE r RECORD; cur RECORD; pass INT; nid INT; dup INT;
        n_moved INT := 0; n_requoted INT := 0; n_same INT := 0; n_absent INT := 0; n_skipped INT := 0; n_mem INT := 0; n_sum INT := 0; n_sum_skip INT := 0;
BEGIN
  FOR pass IN 1..3 LOOP
  FOR r IN SELECT * FROM _s463eb ORDER BY xid LOOP
    IF r.side = 'T' THEN
      SELECT x.id, x.note, t.ch, t.vn, t.es, t.bs, x.source_verse_id AS other_id INTO cur
        FROM cross_references x JOIN _s463ebv t ON t.id = x.target_verse_id WHERE x.id = r.xid;
    ELSE
      SELECT x.id, x.note, s.ch, s.vn, s.es, s.bs, x.target_verse_id AS other_id INTO cur
        FROM cross_references x JOIN _s463ebv s ON s.id = x.source_verse_id WHERE x.id = r.xid;
    END IF;
    IF cur.id IS NULL THEN
      IF pass = 3 THEN n_absent := n_absent + 1; RAISE NOTICE 'S463e card % absent', r.xid; END IF; CONTINUE;
    END IF;
    IF cur.es <> 'apocalypse-of-abraham' OR cur.bs <> r.ob THEN
      IF pass = 3 THEN n_skipped := n_skipped + 1; RAISE NOTICE 'S463e card % extra end is %/% not apocalypse-of-abraham/% — skipped', r.xid, cur.es, cur.bs, r.ob; END IF; CONTINUE;
    END IF;
    IF cur.bs = r.nb AND cur.ch = r.nc AND cur.vn = r.nv AND cur.note = r.new_note THEN
      IF pass = 1 THEN n_same := n_same + 1; END IF; CONTINUE;
    END IF;
    IF NOT (cur.ch = r.oc AND cur.vn = r.ov) AND NOT (cur.bs = r.nb AND cur.ch = r.nc AND cur.vn = r.nv) THEN
      IF pass = 3 THEN n_skipped := n_skipped + 1;
      RAISE NOTICE 'S463e card % is at % %:%, expected %:% — edited since the read-back, skipped', r.xid, cur.bs, cur.ch, cur.vn, r.oc, r.ov; END IF; CONTINUE;
    END IF;
    SELECT id INTO nid FROM _s463ebv WHERE es = 'apocalypse-of-abraham' AND bs = r.nb AND ch = r.nc AND vn = r.nv;
    IF nid IS NULL THEN RAISE EXCEPTION 'S463e: live % %:% missing', r.nb, r.nc, r.nv; END IF;
    IF (SELECT text FROM _s463ebv WHERE id = nid) <> r.live_text THEN
      RAISE EXCEPTION 'S463e: live % %:% text differs from the read-back the fix was written against — re-run the dump and rebuild', r.nb, r.nc, r.nv;
    END IF;
    IF r.quotes_live AND position(r.live_text IN r.new_note) = 0 THEN
      RAISE EXCEPTION 'S463e: new note for card % does not quote the live % %:% verbatim', r.xid, r.nb, r.nc, r.nv;
    END IF;
    IF nid = cur.other_id THEN
      IF pass = 3 THEN n_skipped := n_skipped + 1; RAISE NOTICE 'S463e SKIPPED card % (-> % %:%): that is the card''s other verse', r.xid, r.nb, r.nc, r.nv; END IF;
      CONTINUE;
    END IF;
    IF r.side = 'T' THEN
      SELECT count(*) INTO dup FROM cross_references x WHERE x.source_verse_id = cur.other_id AND x.target_verse_id = nid AND x.id <> r.xid;
    ELSE
      SELECT count(*) INTO dup FROM cross_references x WHERE x.target_verse_id = cur.other_id AND x.source_verse_id = nid AND x.id <> r.xid;
    END IF;
    IF dup > 0 THEN
      IF pass = 3 THEN n_skipped := n_skipped + 1; RAISE NOTICE 'S463e SKIPPED card % (-> % %:%): a card already sits on that pair', r.xid, r.nb, r.nc, r.nv; END IF;
      CONTINUE;
    END IF;
    IF r.side = 'T' THEN UPDATE cross_references SET target_verse_id = nid, note = r.new_note WHERE id = r.xid;
    ELSE UPDATE cross_references SET source_verse_id = nid, note = r.new_note WHERE id = r.xid; END IF;
    IF r.oc = r.nc AND r.ov = r.nv AND r.ob = r.nb THEN n_requoted := n_requoted + 1;
    ELSE n_moved := n_moved + 1; RAISE NOTICE 'S463e moved card %: % %:% -> %:% (%)', r.xid, r.nb, r.oc, r.ov, r.nc, r.nv, CASE WHEN r.side='T' THEN 'target' ELSE 'source' END; END IF;
  END LOOP;
  END LOOP;

  FOR r IN SELECT m.* FROM _s463ebm m LOOP
    UPDATE cross_reference_thread_members SET member_note = r.new_note
     WHERE thread_id = r.thread_id AND cross_reference_id = r.xid AND member_note IS DISTINCT FROM r.new_note;
    IF FOUND THEN n_mem := n_mem + 1; END IF;
  END LOOP;

  FOR r IN SELECT s.* FROM _s463ebs s LOOP
    UPDATE cross_reference_threads SET summary_md = r.new_summary WHERE id = r.thread_id AND summary_md = r.old_summary;
    IF FOUND THEN n_sum := n_sum + 1;
    ELSIF NOT EXISTS (SELECT 1 FROM cross_reference_threads WHERE id = r.thread_id AND summary_md = r.new_summary) THEN
      n_sum_skip := n_sum_skip + 1; RAISE NOTICE 'S463e SKIPPED thread % summary: live text is neither the old nor the new', r.thread_id;
    END IF;
  END LOOP;

  RAISE NOTICE 'S463e (apocalypse-of-abraham) summary: notes rewritten in place %, moved %, already landed %, skipped %, absent %; member notes updated %; summaries updated % (skipped %)',
    n_requoted, n_moved, n_same, n_skipped, n_absent, n_mem, n_sum, n_sum_skip;
  IF n_skipped + n_absent + n_sum_skip > 0 THEN RAISE NOTICE 'S463e: read the SKIPPED/absent lines above — those rows still carry the old text'; END IF;
END $fix$;
COMMIT;
\echo 'session463e (apocalypse-of-abraham) — done.'
